              {isProcessing ? t.processing : t.donateNow}
            </button>
          </div>

          {/* Info Cards */}
          <div className="grid grid-cols-1 gap-4">
            <div className="bg-[#1c2620] p-4 rounded-2xl flex items-start gap-3">
              <span className="material-symbols-outlined text-[#38e07b] text-2xl">
