import { useQuery, useMutation } from "@tanstack/react-query";
import { useLanguage } from "@/context/LanguageContext";
import { useLocation } from "wouter";
import BottomNav from "@/components/BottomNav";
import type { Analysis } from "@shared/schema";
import { APP_VERSION } from "@shared/schema";
import { TrendingUp, TrendingDown, Clock, CheckCircle, XCircle, Trash2, Share2 } from "lucide-react";
import { apiRequest, queryClient } from "@/lib/queryClient";
import { useToast } from "@/hooks/use-toast";
import { useVersionGuard } from "@/hooks/useVersionGuard";

export default function SavedAnalyses() {
  const [, setLocation] = useLocation();
  const { t } = useLanguage();
  const { toast } = useToast();
  const { guardAction, UpdateModal } = useVersionGuard();
  const userId = localStorage.getItem("userId");

  const { data: savedAnalysesRaw = [], isLoading } = useQuery<Analysis[]>({
    queryKey: ["/api/analyses/saved", userId || ""],
    enabled: !!userId,
  });

  const deleteMutation = useMutation({
    mutationFn: async (analysisId: string) => {
      const result = await apiRequest("DELETE", `/api/analysis/${analysisId}`, {
        appVersion: APP_VERSION,
      });
      return await result.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/analyses/saved", userId || ""] });
      toast({
        title: t.deleted,
        description: t.analysisDeletedSuccessfully,
      });
    },
    onError: () => {
      toast({
        title: t.error,
        description: t.failedToDeleteAnalysis,
        variant: "destructive",
      });
    },
  });

  const publishMutation = useMutation({
    mutationFn: async (analysisId: string) => {
      const result = await apiRequest("POST", `/api/community/publish/${analysisId}`, {
        appVersion: APP_VERSION,
      });
      return await result.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/analyses/saved", userId || ""] });
      toast({
        title: t.published,
        description: t.analysisPublishedSuccessfully,
      });
    },
    onError: () => {
      toast({
        title: t.error,
        description: t.failedToPublishAnalysis,
        variant: "destructive",
      });
    },
  });

  const unpublishMutation = useMutation({
    mutationFn: async (analysisId: string) => {
      const result = await apiRequest("POST", `/api/community/unpublish/${analysisId}`, {
        appVersion: APP_VERSION,
      });
      return await result.json();
    },
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ["/api/analyses/saved", userId || ""] });
      toast({
        title: t.unpublished,
        description: t.analysisUnpublishedSuccessfully,
      });
    },
    onError: () => {
      toast({
        title: t.error,
        description: t.failedToUnpublishAnalysis,
        variant: "destructive",
      });
    },
  });

  const handleDelete = (e: React.MouseEvent, analysisId: string, symbolName: string) => {
    e.stopPropagation();

    const confirmed = window.confirm(`Are you sure you want to delete ${symbolName} analysis? This action cannot be undone.`);
    if (confirmed) {
      deleteMutation.mutate(analysisId);
    }
  };

  const handleTogglePublish = async (e: React.MouseEvent, analysisId: string, isPublished: boolean) => {
    e.stopPropagation();

    // VERSION CHECKPOINT
    const versionOk = await guardAction();
    if (!versionOk) return;

    if (isPublished) {
      unpublishMutation.mutate(analysisId);
    } else {
      publishMutation.mutate(analysisId);
    }
  };

  // Sort by newest first
  const savedAnalyses = [...savedAnalysesRaw].sort((a, b) => {
    const dateA = a.createdAt ? new Date(a.createdAt).getTime() : 0;
    const dateB = b.createdAt ? new Date(b.createdAt).getTime() : 0;
    return dateB - dateA; // Newest first
  });

  const getStatusConfig = (status: string) => {
    switch (status) {
      case "won":
        return {
          icon: CheckCircle,
          color: "text-[#38e07b]",
          bgColor: "bg-[#38e07b]/10",
          borderColor: "border-[#38e07b]",
          label: t.won,
        };
      case "lost":
        return {
          icon: XCircle,
          color: "text-red-500",
          bgColor: "bg-red-500/10",
          borderColor: "border-red-500",
          label: t.lost,
        };
      case "expired":
        return {
          icon: Clock,
          color: "text-gray-500",
          bgColor: "bg-gray-500/10",
          borderColor: "border-gray-500",
          label: t.expired,
        };
      default:
        return {
          icon: Clock,
          color: "text-blue-500",
          bgColor: "bg-blue-500/10",
          borderColor: "border-blue-500",
          label: t.active,
        };
    }
  };

  if (isLoading) {
    return (
      <div className="min-h-screen bg-[#111714] flex items-center justify-center">
        <div className="text-white">{t.loadingSavedAnalyses}</div>
      </div>
    );
  }

  // Calculate stats
  const totalTrades = savedAnalyses.length;
  const greenTrades = savedAnalyses.filter(a => a.tradeStatus === "won").length;
  const redTrades = savedAnalyses.filter(a => a.tradeStatus === "lost").length;
  const yellowTrades = savedAnalyses.filter(a => a.tradeStatus === "active" || !a.tradeStatus).length;
  const grayTrades = savedAnalyses.filter(a => a.tradeStatus === "expired").length;

  const totalClosed = greenTrades + redTrades;
  const winRate = totalClosed > 0 ? ((greenTrades / totalClosed) * 100).toFixed(1) : "0.0";
  const lossRate = totalClosed > 0 ? ((redTrades / totalClosed) * 100).toFixed(1) : "0.0";

  return (
    <div className="min-h-screen bg-[#111714] pb-24">
      <header className="bg-[#1c2620] border-b border-[#29382f] px-4 py-6">
        <h1 className="text-white text-2xl font-bold">{t.savedAnalyses}</h1>
        <p className="text-[#9eb7a8] text-sm mt-1">
          {t.trackYourSavedTrades}
        </p>
      </header>

      {/* Traffic Light Stats Dashboard */}
      {totalTrades > 0 && (
        <div className="bg-[#1c2620] border-b border-[#29382f] px-4 py-4">
          <div className="grid grid-cols-5 gap-2 mb-3">
            <div className="text-center">
              <div className="text-2xl font-bold text-white">{totalTrades}</div>
              <div className="text-xs text-[#9eb7a8]">{t.total}</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-[#38e07b]">{greenTrades}</div>
              <div className="text-xs text-[#9eb7a8]">{t.won}</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-red-500">{redTrades}</div>
              <div className="text-xs text-[#9eb7a8]">{t.lost}</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-yellow-500">{yellowTrades}</div>
              <div className="text-xs text-[#9eb7a8]">{t.active}</div>
            </div>
            <div className="text-center">
              <div className="text-2xl font-bold text-gray-500">{grayTrades}</div>
              <div className="text-xs text-[#9eb7a8]">{t.expired}</div>
            </div>
          </div>
          {totalClosed > 0 && (
            <div className="flex gap-2">
              <div className="flex-1 bg-[#111714] rounded-lg p-2 text-center">
                <div className="text-sm font-medium text-[#38e07b]">{winRate}%</div>
                <div className="text-xs text-[#9eb7a8]">{t.winRate}</div>
              </div>
              <div className="flex-1 bg-[#111714] rounded-lg p-2 text-center">
                <div className="text-sm font-medium text-red-500">{lossRate}%</div>
                <div className="text-xs text-[#9eb7a8]">{t.lossRate}</div>
              </div>
            </div>
          )}
        </div>
      )}

      <main className="px-4 py-6">
        {savedAnalyses.length === 0 ? (
          <div className="text-center py-12">
            <div className="text-[#9eb7a8] text-lg mb-2">{t.noSavedAnalysesYet}</div>
            <p className="text-[#9eb7a8] text-sm mb-6">
              {t.saveAnalysesToTrack}
            </p>
            <button
              onClick={() => setLocation("/analyzer")}
              className="bg-[#38e07b] text-[#111714] font-bold py-3 px-6 rounded-full hover:bg-opacity-90 transition-colors"
              data-testid="button-go-to-analyzer"
            >
              {t.analyzeMarket}
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            {savedAnalyses.map((analysis) => {
              const isBullish = analysis.sentiment === "Bullish";
              const statusConfig = getStatusConfig(analysis.tradeStatus || "active");
              const StatusIcon = statusConfig.icon;

              return (
                <div
                  key={analysis.id}
                  onClick={() => setLocation(`/analyzer?analysisId=${analysis.id}&fromSaved=true`)}
                  className="bg-[#1c2620] border border-[#29382f] rounded-xl p-3 cursor-pointer hover:border-[#38e07b] transition-colors"
                  data-testid={`card-saved-analysis-${analysis.id}`}
                >
                  {/* Line 1: Symbol, Sentiment + Verdict, RRR, Status, Delete */}
                  <div className="flex items-center justify-between gap-2 mb-2">
                    <div className="flex items-center gap-2 flex-1 min-w-0">
                      <span className="text-white font-bold text-base truncate">
                        {analysis.symbol}
                      </span>
                      <div className="flex items-center gap-1">
                        {isBullish ? (
                          <TrendingUp className="w-4 h-4 text-[#38e07b]" />
                        ) : (
                          <TrendingDown className="w-4 h-4 text-red-500" />
                        )}
                        <span className={`text-sm font-medium ${isBullish ? "text-[#38e07b]" : "text-red-500"}`}>
                          {analysis.sentiment}
                        </span>
                      </div>
                    </div>
                    <div className="flex items-center gap-2 flex-shrink-0">
                      <div className={`flex items-center gap-1 px-2 py-0.5 rounded-full ${statusConfig.bgColor} ${statusConfig.borderColor} border`}>
                        <StatusIcon className={`w-3 h-3 ${statusConfig.color}`} />
                        <span className={`text-xs font-medium ${statusConfig.color}`}>
                          {statusConfig.label}
                        </span>
                      </div>
                      <button
                        onClick={(e) => handleTogglePublish(e, analysis.id, analysis.isPublished === 1)}
                        disabled={publishMutation.isPending || unpublishMutation.isPending}
                        className={`p-1.5 rounded-full border transition-colors disabled:opacity-50 ${
                          analysis.isPublished === 1
                            ? "bg-[#38e07b]/20 border-[#38e07b]/40 hover:bg-[#38e07b]/30"
                            : "bg-gray-500/10 border-gray-500/30 hover:bg-gray-500/20"
                        }`}
                        data-testid={`button-publish-analysis-${analysis.id}`}
                        title={analysis.isPublished === 1 ? "Unpublish from community" : "Publish to community"}
                      >
                        <Share2 className={`w-4 h-4 ${analysis.isPublished === 1 ? "text-[#38e07b]" : "text-gray-400"}`} />
                      </button>
                      <button
                        onClick={(e) => handleDelete(e, analysis.id, analysis.symbol)}
                        disabled={deleteMutation.isPending}
                        className="p-1.5 rounded-full bg-red-500/10 border border-red-500/30 hover:bg-red-500/20 transition-colors disabled:opacity-50"
                        data-testid={`button-delete-analysis-${analysis.id}`}
                        title="Delete analysis"
                      >
                        <Trash2 className="w-4 h-4 text-red-500" />
                      </button>
                    </div>
                  </div>

                  {/* Line 2: Entry, Current, TP1, TP2, SL */}
                  <div className="flex items-center gap-2 text-xs mb-1">
                    <div className="flex items-center gap-1">
                      <span className="text-[#9eb7a8]">Entry:</span>
                      <span className="text-white font-medium">{analysis.entry || "N/A"}</span>
                    </div>
                    <span className="text-[#9eb7a8]">•</span>
                    <div className="flex items-center gap-1">
                      <span className="text-[#9eb7a8]">Now:</span>
                      <span className="text-white font-medium">{analysis.currentPrice || analysis.livePrice || "N/A"}</span>
                    </div>
                    <span className="text-[#9eb7a8]">•</span>
                    <div className="flex items-center gap-1">
                      <span className="text-[#38e07b]">TP1:</span>
                      <span className="text-[#38e07b] font-medium">{analysis.tp1 || "N/A"}</span>
                    </div>
                    <span className="text-[#9eb7a8]">•</span>
                    <div className="flex items-center gap-1">
                      <span className="text-red-500">SL:</span>
                      <span className="text-red-500 font-medium">{analysis.stopLoss || "N/A"}</span>
                    </div>
                  </div>

                  {/* Line 3: Timestamp */}
                  {analysis.createdAt && (
                    <div className="flex items-center gap-1 text-[10px] text-[#6a7f72]">
                      <span className="material-symbols-outlined text-xs">schedule</span>
                      <span>
                        {new Date(analysis.createdAt).toLocaleDateString(undefined, { 
                          year: 'numeric', 
                          month: 'short', 
                          day: 'numeric' 
                        })}
                        {' '}
                        {new Date(analysis.createdAt).toLocaleTimeString(undefined, { 
                          hour: '2-digit', 
                          minute: '2-digit'
                        })}
                      </span>
                    </div>
                  )}
                </div>
              );
            })}
          </div>
        )}
      </main>

      <BottomNav />
      <UpdateModal />
    </div>
  );
}

server/priceData.ts.content:
/**
 * Price Data Fetching Service
 * 
 * Fetches accurate real-time + closed candle prices from:
 * - Yahoo Finance (stocks, forex, commodities, bonds)
 * - Binance (cryptocurrencies)
 * 
 * NO API KEYS REQUIRED - Completely FREE!
 */

import { normalizeSymbolForAPI, type MarketType, type SymbolClassification } from "./symbolRegistry";

interface CandleData {
  timestamp: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
}

interface OHLCVData {
  symbol: string;
  livePrice: number;
  candleClosePrice: number;
  candleCloseTime: string;
  timeframe: string;
  open: number;
  high: number;
  low: number;
  close: number;
  volume: number;
  dataSource: string;
  historicalCandles: CandleData[];
}

/**
 * Get appropriate timeframe based on duration
 */
function getTimeframeForDuration(duration: string): { interval: string; label: string; candleCount: number } {
  switch (duration) {
    case "scalping":
      return { interval: "5m", label: "5min", candleCount: 72 }; // 6 hours
    case "swing_trade":
      return { interval: "15m", label: "15min", candleCount: 48 }; // 12 hours
    case "short_term":
      return { interval: "1h", label: "1hr", candleCount: 50 }; // ~2 days
    case "long_term":
      return { interval: "1d", label: "1day", candleCount: 30 }; // 1 month
    default:
      return { interval: "1h", label: "1hr", candleCount: 50 };
  }
}

/**
 * Fetch cryptocurrency prices from Binance with CoinGecko fallback
 * Completely FREE - no API key required
 */
async function fetchCryptoPrice(
  symbol: string,
  duration: string
): Promise<OHLCVData> {
  const { interval, label, candleCount } = getTimeframeForDuration(duration);

  // Convert symbol to Binance format (e.g., "BTC" -> "BTCUSDT", "ETH" -> "ETHUSDT")
  let cleanSymbol = symbol.toUpperCase().replace(/[^A-Z0-9]/g, "");

  // Remove USD/USDT suffix to get base symbol
  const baseSymbol = cleanSymbol
    .replace(/USDT$/g, "")
    .replace(/USD$/g, "");

  // Construct Binance symbol
  let binanceSymbol = `${baseSymbol}USDT`;

  // Fallback conversions for common symbols
  const symbolMap: Record<string, string> = {
    "BTC": "BTCUSDT",
    "BITCOIN": "BTCUSDT",
    "ETH": "ETHUSDT",
    "ETHEREUM": "ETHUSDT",
    "BNB": "BNBUSDT",
    "SOL": "SOLUSDT",
    "SOLANA": "SOLUSDT",
    "XRP": "XRPUSDT",
    "ADA": "ADAUSDT",
    "CARDANO": "ADAUSDT",
    "DOGE": "DOGEUSDT",
    "DOGECOIN": "DOGEUSDT",
    "1INCH": "1INCHUSDT",
    "1000SATS": "1000SATSUSDT",
    "AVAX": "AVAXUSDT",
    "MATIC": "MATICUSDT",
    "LINK": "LINKUSDT",
    "DOT": "DOTUSDT",
  };

  if (symbolMap[baseSymbol]) {
    binanceSymbol = symbolMap[baseSymbol];
  }

  console.log(`[fetchCryptoPrice] Symbol: "${symbol}" → Base: "${baseSymbol}" → Binance: "${binanceSymbol}"`);

  // Try Binance first (will fail with 451 on Replit)
  try {
    const tickerUrl = `https://api.binance.com/api/v3/ticker/price?symbol=${binanceSymbol}`;
    const tickerResponse = await fetch(tickerUrl);

    if (tickerResponse.status === 451) {
      console.log(`[fetchCryptoPrice] Binance blocked (451), falling back to CoinGecko`);
      return await fetchCryptoPriceFromCoinGecko(baseSymbol, binanceSymbol, interval, label);
    }

    if (!tickerResponse.ok) {
      throw new Error(`Binance ticker API error: ${tickerResponse.status}`);
    }

    const tickerData = await tickerResponse.json();
    const livePrice = parseFloat(tickerData.price);

    // Fetch OHLCV candle data - get enough candles for historical analysis
    // Add 1 extra to ensure we have enough closed candles
    const klinesUrl = `https://api.binance.com/api/v3/klines?symbol=${binanceSymbol}&interval=${interval}&limit=${candleCount + 1}`;
    const klinesResponse = await fetch(klinesUrl);

    if (!klinesResponse.ok) {
      throw new Error(`Binance klines API error: ${klinesResponse.status}`);
    }

    const klinesData = await klinesResponse.json();

    // Get all closed candles (excluding the last incomplete one)
    const closedCandles = klinesData.slice(0, -1);
    const closedCandle = closedCandles[closedCandles.length - 1];

    if (!closedCandle) {
      throw new Error("No closed candle data available");
    }

    const candleCloseTime = new Date(closedCandle[6]).toISOString().replace('T', ' ').replace('Z', ' UTC');

    // Build historical candles array
    const historicalCandles: CandleData[] = closedCandles.map((candle: any) => ({
      timestamp: new Date(candle[0]).toISOString().replace('T', ' ').replace('Z', ' UTC'),
      open: parseFloat(candle[1]),
      high: parseFloat(candle[2]),
      low: parseFloat(candle[3]),
      close: parseFloat(candle[4]),
      volume: parseFloat(candle[5]),
    }));

    console.log(`[Binance] ✅ Fetched ${historicalCandles.length} historical ${label} candles for ${binanceSymbol}`);

    return {
      symbol: binanceSymbol,
      livePrice: livePrice,
      candleClosePrice: parseFloat(closedCandle[4]),
      candleCloseTime,
      timeframe: label,
      open: parseFloat(closedCandle[1]),
      high: parseFloat(closedCandle[2]),
      low: parseFloat(closedCandle[3]),
      close: parseFloat(closedCandle[4]),
      volume: parseFloat(closedCandle[5]),
      dataSource: "Binance",
      historicalCandles,
    };
  } catch (error: any) {
    console.error(`❌ Binance API error for symbol "${symbol}":`, error.message);
    console.log(`[fetchCryptoPrice] Attempting CoinGecko fallback...`);
    return await fetchCryptoPriceFromCoinGecko(baseSymbol, binanceSymbol, interval, label);
  }
}

/**
 * Fetch crypto price from CoinGecko (fallback when Binance is blocked)
 */
async function fetchCryptoPriceFromCoinGecko(
  baseSymbol: string,
  binanceSymbol: string,
  interval: string,
  label: string
): Promise<OHLCVData> {
  const coinGeckoMap: Record<string, string> = {
    'BTC': 'bitcoin',
    'ETH': 'ethereum',
    'BNB': 'binancecoin',
    'XRP': 'ripple',
    'SOL': 'solana',
    'ADA': 'cardano',
    'DOGE': 'dogecoin',
    'MATIC': 'matic-network',
    'DOT': 'polkadot',
    'AVAX': 'avalanche-2',
    'LINK': 'chainlink',
    'UNI': 'uniswap',
    'ATOM': 'cosmos',
    'LTC': 'litecoin',
    'BCH': 'bitcoin-cash',
  };

  const coinGeckoId = coinGeckoMap[baseSymbol];

  if (!coinGeckoId) {
    throw new Error(`Cryptocurrency "${baseSymbol}" not supported. Supported: ${Object.keys(coinGeckoMap).join(', ')}`);
  }

  try {
    // Fetch current price from CoinGecko
    const response = await fetch(
      `https://api.coingecko.com/api/v3/simple/price?ids=${coinGeckoId}&vs_currencies=usd`
    );

    if (!response.ok) {
      throw new Error(`CoinGecko API error: ${response.status}`);
    }

    const data = await response.json();
    const currentPrice = data[coinGeckoId]?.usd;

    if (!currentPrice) {
      throw new Error(`No price data found for ${baseSymbol}`);
    }

    console.log(`[CoinGecko] ✅ Fetched ${baseSymbol}: $${currentPrice}`);

    // For CoinGecko, we only get current price, not historical candles
    // Use current price as both live and close price
    const now = new Date();
    const candleCloseTime = now.toISOString().replace('T', ' ').replace('Z', ' UTC');

    return {
      symbol: binanceSymbol,
      livePrice: currentPrice,
      candleClosePrice: currentPrice, // Same as live for CoinGecko
      candleCloseTime,
      timeframe: label,
      open: currentPrice,
      high: currentPrice,
      low: currentPrice,
      close: currentPrice,
      volume: 0, // No volume data from CoinGecko simple API
      dataSource: "CoinGecko",
      historicalCandles: [], // CoinGecko simple API doesn't provide historical data
    };
  } catch (error: any) {
    console.error(`❌ CoinGecko API error for symbol "${baseSymbol}":`, error.message);
    throw new Error(`Failed to fetch crypto price for "${baseSymbol}": ${error.message}`);
  }
}

/**
 * Fetch stock/forex/commodity prices from Yahoo Finance
 * Completely FREE - no API key required
 */
async function fetchYahooFinancePrice(
  symbol: string,
  duration: string,
  market: string
): Promise<OHLCVData> {
  try {
    const { interval, label, candleCount } = getTimeframeForDuration(duration);

    // Yahoo Finance interval mapping
    const yahooIntervalMap: Record<string, string> = {
      "5m": "5m",
      "15m": "15m",
      "1h": "1h",
      "1d": "1d",
    };

    const yahooInterval = yahooIntervalMap[interval] || "1h";

    // Use unified symbol normalization from symbolRegistry
    // This ensures consistent transformation logic across the entire codebase
    // Classification is auto-detected based on symbol pattern and market type
    const yahooSymbol = normalizeSymbolForAPI(symbol, market as MarketType);

    // Fetch chart data from Yahoo Finance - adjust range to get enough historical data
    const rangeMap: Record<string, string> = {
      "scalping": "1d",      // 5m x 72 = 6 hours
      "swing_trade": "3d",   // 15m x 48 = 12 hours
      "short_term": "7d",    // 1h x 50 = ~2 days
      "long_term": "3mo",    // 1d x 30 = 1 month
    };
    const range = rangeMap[duration] || "5d";
    const url = `https://query1.finance.yahoo.com/v8/finance/chart/${yahooSymbol}?interval=${yahooInterval}&range=${range}`;

    const response = await fetch(url, {
      headers: {
        "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
      },
    });

    if (!response.ok) {
      throw new Error(`Yahoo Finance API error: ${response.status}`);
    }

    const data = await response.json();

    if (!data.chart || !data.chart.result || data.chart.result.length === 0) {
      throw new Error("No data returned from Yahoo Finance");
    }

    const result = data.chart.result[0];
    const meta = result.meta;
    const quote = result.indicators.quote[0];
    const timestamps = result.timestamp;

    if (!timestamps || timestamps.length === 0) {
      throw new Error("No timestamp data available");
    }

    // Live price from meta
    const livePrice = meta.regularMarketPrice || meta.previousClose;

    // Get all closed candles (exclude the last incomplete one)
    const totalCandles = timestamps.length;
    const numClosedCandles = Math.min(candleCount, totalCandles - 1);
    const startIndex = Math.max(0, totalCandles - 1 - numClosedCandles);
    const endIndex = totalCandles - 1;

    // Get the last CLOSED candle
    const closedCandleIndex = endIndex;
    const candleCloseTime = new Date(timestamps[closedCandleIndex] * 1000).toISOString().replace('T', ' ').replace('Z', ' UTC');

    // Build historical candles array from closed candles
    const historicalCandles: CandleData[] = [];
    for (let i = startIndex; i < endIndex; i++) {
      // Skip null/invalid candles
      if (quote.close[i] !== null && quote.close[i] !== undefined) {
        historicalCandles.push({
          timestamp: new Date(timestamps[i] * 1000).toISOString().replace('T', ' ').replace('Z', ' UTC'),
          open: quote.open[i] || 0,
          high: quote.high[i] || 0,
          low: quote.low[i] || 0,
          close: quote.close[i],
          volume: quote.volume[i] || 0,
        });
      }
    }

    console.log(`[Yahoo Finance] ✅ Fetched ${historicalCandles.length} historical ${label} candles for ${yahooSymbol}`);

    return {
      symbol: yahooSymbol,
      livePrice: livePrice,
      candleClosePrice: quote.close[closedCandleIndex],
      candleCloseTime,
      timeframe: label,
      open: quote.open[closedCandleIndex],
      high: quote.high[closedCandleIndex],
      low: quote.low[closedCandleIndex],
      close: quote.close[closedCandleIndex],
      volume: quote.volume[closedCandleIndex],
      dataSource: "Yahoo Finance",
      historicalCandles,
    };
  } catch (error: any) {
    console.error(`❌ Yahoo Finance API error for symbol "${symbol}" (${market} market):`, error.message);
    throw new Error(`Failed to fetch ${market} price for "${symbol}": ${error.message}`);
  }
}

/**
 * Main function to fetch price data based on market type
 */
export async function fetchMarketPrice(
  symbol: string,
  duration: string,
  market: string
): Promise<OHLCVData> {
  if (market === "cryptocurrency") {
    return await fetchCryptoPrice(symbol, duration);
  } else {
    return await fetchYahooFinancePrice(symbol, duration, market);
  }
}

server/symbolValidator.ts.content:
/**
 * Symbol Validation & Autocomplete Service
 * 
 * Validates trading symbols and provides suggestions based on market type.
 * Fetches initial data to prepare comprehensive context for analysis.
 */

import { normalizeSymbolForAPI, type MarketType, type SymbolClassification } from "./symbolRegistry";

interface SymbolValidationResult {
  isValid: boolean;
  correctedSymbol?: string;
  assetName?: string;
  currentPrice?: number;
  sourceCurrency?: string; // Currency that Yahoo Finance/exchange provides the price in
  suggestions?: Array<{
    symbol: string;
    name: string;
    price?: number;
  }>;
  error?: string;
}

/**
 * Check if a symbol represents a forex pair (e.g., CADUSD=X, EUR/USD, GBPUSD)
 * Forex pairs should NOT be converted to user's currency preference
 */
export function isForexPair(symbol: string): boolean {
  const upperSymbol = symbol.toUpperCase();

  // Yahoo Finance forex pairs end with =X
  if (upperSymbol.includes('=X')) {
    return true;
  }

  // Forex pairs with / separator
  if (upperSymbol.includes('/')) {
    return true;
  }

  // Common forex pair patterns (6-8 character currency pairs)
  // Examples: EURUSD, GBPJPY, USDINR, etc.
  const forexPairPattern = /^[A-Z]{6,8}$/;
  if (forexPairPattern.test(upperSymbol)) {
    // Check if it looks like XXXYYY where XXX and YYY are currency codes
    const commonCurrencies = ['USD', 'EUR', 'GBP', 'JPY', 'CHF', 'CAD', 'AUD', 'NZD', 'INR', 'CNY', 'HKD', 'SGD'];
    const firstThree = upperSymbol.substring(0, 3);
    const secondThree = upperSymbol.substring(3, 6);

    if (commonCurrencies.includes(firstThree) && commonCurrencies.includes(secondThree)) {
      return true;
    }
  }

  return false;
}

/**
 * Extract quote currency (2nd currency) from forex pair
 * Examples:
 * - USD/GBP → GBP
 * - GBPUSD → USD
 * - EURUSD=X → USD
 */
export function getQuoteCurrency(symbol: string): string | null {
  const upperSymbol = symbol.toUpperCase().replace(/=X$/g, '').replace(/\//g, '');

  // Check if it's a 6-character forex pair
  if (upperSymbol.length === 6) {
    // Comprehensive list of all supported currencies (expanded from 19 to 30+)
    const commonCurrencies = [
      'USD', 'EUR', 'GBP', 'JPY', 'CHF', 'CAD', 'AUD', 'NZD',  // Major currencies
      'INR', 'CNY', 'HKD', 'SGD', 'KRW', 'THB',                // Asian currencies
      'MXN', 'BRL', 'ARS', 'CLP', 'COP',                       // Latin American currencies
      'ZAR', 'NGN', 'KES', 'EGP',                              // African currencies
      'RUB', 'TRY', 'PLN', 'HUF', 'CZK', 'RON',              // Eastern European currencies
      'SEK', 'NOK', 'DKK', 'ISK',                              // Nordic currencies
      'ILS', 'AED', 'SAR', 'QAR', 'KWD',                       // Middle Eastern currencies
      'PHP', 'IDR', 'MYR', 'VND'                               // Southeast Asian currencies
    ];
    const quoteCurrency = upperSymbol.substring(3, 6);

    if (commonCurrencies.includes(quoteCurrency)) {
      return quoteCurrency;
    }
  }

  return null;
}

/**
 * Get the currency that Yahoo Finance provides prices in for a given symbol
 * Maps exchange suffixes to their native currencies
 * 
 * For forex pairs, returns the QUOTE CURRENCY (2nd currency in pair)
 * Examples:
 * - USD/GBP → GBP (price is in GBP)
 * - GBP/USD → USD (price is in USD)
 * - EUR/USD → USD (price is in USD)
 */
export function getExchangeCurrency(symbol: string, market: string): string {
  // Forex pairs: return the quote currency (2nd currency)
  // The pair price is always expressed in the quote currency
  if (market === 'forex' || isForexPair(symbol)) {
    const quoteCurrency = getQuoteCurrency(symbol);
    if (quoteCurrency) {
      console.log(`[Forex] ${symbol} → Quote currency: ${quoteCurrency}`);
      return quoteCurrency;
    }
    // Fallback: if we can't determine, return 'FOREX_PAIR' marker
    return 'FOREX_PAIR';
  }

  // Cryptocurrency prices are always in USD from Binance/CoinGecko
  if (market === 'cryptocurrency') {
    return 'USD';
  }

  // Check exchange suffix for stocks/commodities
  const upperSymbol = symbol.toUpperCase();

  // CRITICAL: Commodity futures (=F suffix) MUST be checked BEFORE exchange suffixes
  // to prevent false matches (e.g., SI=F should NOT match Singapore .SI)
  // ALL commodity futures from Yahoo Finance are priced in USD
  // Using .includes() instead of .endsWith() to catch any =F anywhere in the symbol
  if (upperSymbol.includes('=F')) {
    console.log(`[Commodity Futures] ${symbol} → Source currency: USD (=F suffix detected)`);
    return 'USD';
  }

  // ADDITIONAL SAFETY CHECK: If symbol starts with common commodity ticker + =F pattern
  // Examples: GC=F, SI=F, CL=F, NG=F, BZ=F, etc.
  const commodityFuturesPattern = /^[A-Z]{1,3}=F$/;
  if (commodityFuturesPattern.test(upperSymbol)) {
    console.log(`[Commodity Futures Pattern Match] ${symbol} → Source currency: USD`);
    return 'USD';
  }

  // Indian exchanges
  if (upperSymbol.endsWith('.NS') || upperSymbol.endsWith('.BO')) {
    return 'INR';
  }

  // UK exchange
  if (upperSymbol.endsWith('.L')) {
    return 'GBP';
  }

  // Tokyo exchange
  if (upperSymbol.endsWith('.T')) {
    return 'JPY';
  }

  // Hong Kong exchange
  if (upperSymbol.endsWith('.HK')) {
    return 'HKD';
  }

  // Australian exchange
  if (upperSymbol.endsWith('.AX')) {
    return 'AUD';
  }

  // Toronto exchange
  if (upperSymbol.endsWith('.TO')) {
    return 'CAD';
  }

  // Swiss exchange
  if (upperSymbol.endsWith('.SW')) {
    return 'CHF';
  }

  // European exchanges
  if (upperSymbol.endsWith('.PA') || upperSymbol.endsWith('.DE') || upperSymbol.endsWith('.AS')) {
    return 'EUR';
  }

  // Singapore exchange
  if (upperSymbol.endsWith('.SI')) {
    return 'SGD';
  }

  // Saudi Arabia exchange
  if (upperSymbol.endsWith('.SR')) {
    return 'SAR';
  }

  // Brazil exchange
  if (upperSymbol.endsWith('.SA')) {
    return 'BRL';
  }

  // Mexico exchange
  if (upperSymbol.endsWith('.MX')) {
    return 'MXN';
  }

  // Default to USD for US symbols (no suffix) and commodities
  return 'USD';
}

/**
 * Simple in-memory cache for crypto prices to avoid CoinGecko rate limits
 */
interface CacheEntry {
  data: any;
  timestamp: number;
}

const priceCache = new Map<string, CacheEntry>();
const CACHE_TTL_MS = 60000; // 60 seconds

function getCachedPrice(coinGeckoId: string): number | null {
  const cached = priceCache.get(coinGeckoId);
  if (cached && (Date.now() - cached.timestamp) < CACHE_TTL_MS) {
    console.log(`[Cache HIT] ${coinGeckoId}: $${cached.data}`);
    return cached.data;
  }
  return null;
}

function setCachedPrice(coinGeckoId: string, price: number): void {
  priceCache.set(coinGeckoId, {
    data: price,
    timestamp: Date.now(),
  });
  console.log(`[Cache SET] ${coinGeckoId}: $${price}`);
}

/**
 * Validate cryptocurrency symbol and get suggestions
 */
async function validateCryptoSymbol(symbol: string): Promise<SymbolValidationResult> {
  try {
    const cleanSymbol = symbol.toUpperCase().replace(/[^A-Z0-9]/g, "");
    console.log(`[validateCrypto] Input symbol: "${symbol}" → Cleaned: "${cleanSymbol}"`);

    // Try direct Binance lookup
    // Remove USD/USDT suffix first, then add USDT properly
    let baseSymbol = cleanSymbol
      .replace(/USDT$/g, "")  // Remove USDT suffix
      .replace(/USD$/g, "");   // Remove USD suffix

    let binanceSymbol = `${baseSymbol}USDT`;
    console.log(`[validateCrypto] Base symbol: "${baseSymbol}" → Binance symbol: "${binanceSymbol}"`);

    try {
      const tickerUrl = `https://api.binance.com/api/v3/ticker/price?symbol=${binanceSymbol}`;
      console.log(`[validateCrypto] Fetching: ${tickerUrl}`);
      const response = await fetch(tickerUrl);

      if (response.ok) {
        const data = await response.json();
        console.log(`[validateCrypto] ✅ Found on Binance:`, data);
        return {
          isValid: true,
          correctedSymbol: binanceSymbol,
          assetName: cleanSymbol, // Will be enriched by Perplexity
          currentPrice: parseFloat(data.price),
          sourceCurrency: 'USD', // Crypto prices are always in USD
        };
      } else if (response.status === 451) {
        // Binance blocked by region - try alternative approach using CoinGecko API
        console.log(`[validateCrypto] ⚠️ Binance blocked (451). Trying alternative...`);
        return await validateCryptoAlternative(cleanSymbol, binanceSymbol);
      } else {
        console.log(`[validateCrypto] ❌ Binance response not OK: ${response.status} ${response.statusText}`);
      }
    } catch (err) {
      console.log(`[validateCrypto] ⚠️ Binance fetch error:`, err);
      // Symbol not found, continue to suggestions
    }

    // Symbol not found directly - fetch popular crypto suggestions
    console.log(`[validateCrypto] Fetching suggestions for: "${cleanSymbol}"`);
    const suggestions = await fetchCryptoSuggestions(cleanSymbol);
    console.log(`[validateCrypto] Found ${suggestions.length} suggestions:`, suggestions);

    if (suggestions.length > 0) {
      return {
        isValid: false,
        suggestions,
        error: `Symbol "${symbol}" not found. Did you mean one of these?`,
      };
    }

    return {
      isValid: false,
      error: `Cryptocurrency symbol "${symbol}" not found. Please check the spelling.`,
    };
  } catch (error: any) {
    return {
      isValid: false,
      error: `Failed to validate symbol: ${error.message}`,
    };
  }
}

/**
 * Alternative crypto validation using CoinGecko (when Binance is blocked)
 */
async function validateCryptoAlternative(cleanSymbol: string, binanceSymbol: string): Promise<SymbolValidationResult> {
  try {
    // Use CoinGecko for popular cryptocurrencies
    const coinGeckoMap: Record<string, string> = {
      'BTC': 'bitcoin',
      'ETH': 'ethereum',
      'BNB': 'binancecoin',
      'XRP': 'ripple',
      'SOL': 'solana',
      'ADA': 'cardano',
      'DOGE': 'dogecoin',
      'MATIC': 'matic-network',
      'DOT': 'polkadot',
      'AVAX': 'avalanche-2',
      'LINK': 'chainlink',
      'UNI': 'uniswap',
      'ATOM': 'cosmos',
      'LTC': 'litecoin',
      'BCH': 'bitcoin-cash',
    };

    const baseSymbol = cleanSymbol
      .replace(/USDT$/g, "")
      .replace(/USD$/g, "");

    const coinGeckoId = coinGeckoMap[baseSymbol];

    if (coinGeckoId) {
      // Check cache first
      const cachedPrice = getCachedPrice(coinGeckoId);
      if (cachedPrice) {
        return {
          isValid: true,
          correctedSymbol: binanceSymbol,
          assetName: cleanSymbol,
          currentPrice: cachedPrice,
          sourceCurrency: 'USD', // Crypto prices are always in USD
        };
